import { Controller, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const VISIBILITY_SCOPES = ['전체', '부서', '개인'];
const APPROVAL_VALUES = ['미사용', '사용'];

function toId(value: unknown): number | null {
  if (value === null || value === undefined || value === '') {
    return null;
  }
  const n = Number(value);
  if (!Number.isInteger(n) || n <= 0) {
    throw new ApiError(400, 'VALIDATION_FAILED', 'ID는 양의 정수여야 합니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr03304Controller {
  @Put('/resources/:resourceId/settings')
  async updateResourceSettings(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자원 담당자');
    const data = checks.inputOf(req.body);
    const resourceId = toId(req.params['resourceId']);
    if (resourceId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자원 ID가 필요합니다.');
    }

    const approvalRequired = data['approvalRequired'];
    if (typeof approvalRequired !== 'string' || !APPROVAL_VALUES.includes(approvalRequired)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '승인 절차 사용 여부는 미사용 또는 사용이어야 합니다.');
    }
    const visibilityScope = data['visibilityScope'];
    if (typeof visibilityScope !== 'string' || visibilityScope === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '공개범위를 입력해 주세요.');
    }
    if (!VISIBILITY_SCOPES.includes(visibilityScope)) {
      throw new ApiError(422, 'INVALID_VISIBILITY_SCOPE', '공개범위는 전체, 부서, 개인 중 하나여야 합니다.');
    }
    const approverEmployeeId = toId(data['approverEmployeeId']);
    if (approvalRequired === '사용' && approverEmployeeId === null) {
      throw new ApiError(422, 'APPROVER_REQUIRED', '승인 절차를 사용하려면 승인 담당자를 지정해 주세요.');
    }

    const rawPermissions = data['permissions'];
    if (!Array.isArray(rawPermissions)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 목록이 필요합니다.');
    }
    const permissions: { employeeId: number | null; departmentId: number | null; usageScope: string | null }[] = [];
    const permissionKeys = new Set<string>();
    for (const item of rawPermissions) {
      if (item === null || typeof item !== 'object') {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 항목 형식이 올바르지 않습니다.');
      }
      const p = item as Record<string, unknown>;
      const employeeId = toId(p['employeeId']);
      const departmentId = toId(p['departmentId']);
      if ((employeeId === null) === (departmentId === null)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 대상은 임직원 또는 부서 중 하나만 지정해 주세요.');
      }
      const scopeRaw = p['usageScope'];
      if (scopeRaw !== undefined && scopeRaw !== null && typeof scopeRaw !== 'string') {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 범위는 글자여야 합니다.');
      }
      const usageScope = typeof scopeRaw === 'string' && scopeRaw !== '' ? scopeRaw : null;
      if (usageScope !== null && usageScope.length > 100) {
        throw new ApiError(400, 'VALIDATION_FAILED', '사용 범위는 100자 이하여야 합니다.');
      }
      const key = employeeId !== null ? 'e' + employeeId : 'd' + departmentId;
      if (permissionKeys.has(key)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '같은 사용 권한 대상이 중복되었습니다.');
      }
      permissionKeys.add(key);
      permissions.push({ employeeId, departmentId, usageScope });
    }

    const rawAttributes = data['attributes'] === undefined || data['attributes'] === null ? [] : data['attributes'];
    if (!Array.isArray(rawAttributes)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '자원 속성 목록 형식이 올바르지 않습니다.');
    }
    const attributes: { name: string; value: string }[] = [];
    const attributeNames = new Set<string>();
    for (const item of rawAttributes) {
      if (item === null || typeof item !== 'object') {
        throw new ApiError(400, 'VALIDATION_FAILED', '자원 속성 항목 형식이 올바르지 않습니다.');
      }
      const a = item as Record<string, unknown>;
      const name = a['name'];
      const value = a['value'];
      if (typeof name !== 'string' || name.trim() === '' || typeof value !== 'string' || value.trim() === '') {
        throw new ApiError(400, 'VALIDATION_FAILED', '속성명과 속성값을 모두 입력해 주세요.');
      }
      if (name.length > 100 || value.length > 500) {
        throw new ApiError(400, 'VALIDATION_FAILED', '속성명은 100자, 속성값은 500자 이하여야 합니다.');
      }
      if (attributeNames.has(name)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '속성명이 중복되었습니다.');
      }
      attributeNames.add(name);
      attributes.push({ name, value });
    }

    return transaction(async (db) => {
      const found = await db.query(
        'SELECT resource_id FROM resource WHERE resource_id = CAST(:resourceId AS bigint) FOR UPDATE',
        { resourceId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'RESOURCE_NOT_FOUND', '설정할 자원을 찾을 수 없습니다.');
      }

      if (approverEmployeeId !== null) {
        const emp = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
          { id: approverEmployeeId },
        );
        if (emp.length === 0) {
          throw new ApiError(400, 'VALIDATION_FAILED', '승인 담당자 임직원을 찾을 수 없습니다.');
        }
      }
      for (const p of permissions) {
        if (p.employeeId !== null) {
          const emp = await db.query(
            'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
            { id: p.employeeId },
          );
          if (emp.length === 0) {
            throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 대상 임직원을 찾을 수 없습니다.');
          }
        } else {
          const dep = await db.query(
            'SELECT department_id FROM department WHERE department_id = CAST(:id AS bigint)',
            { id: p.departmentId },
          );
          if (dep.length === 0) {
            throw new ApiError(400, 'VALIDATION_FAILED', '사용 권한 대상 부서를 찾을 수 없습니다.');
          }
        }
      }

      // 승인 절차 변경은 이후 신규 예약부터 적용된다 (기존 예약은 건드리지 않는다).
      await db.execute(
        'UPDATE resource SET approval_required = :approvalRequired, visibility_scope = :visibilityScope, updated_at = now() WHERE resource_id = CAST(:resourceId AS bigint)',
        { approvalRequired, visibilityScope, resourceId },
      );

      await db.execute('DELETE FROM resource_permission WHERE resource_id = CAST(:resourceId AS bigint)', { resourceId });
      for (const p of permissions) {
        await db.execute(
          'INSERT INTO resource_permission (resource_id, employee_id, department_id, usage_scope, created_at, updated_at) VALUES (CAST(:resourceId AS bigint), CAST(:employeeId AS bigint), CAST(:departmentId AS bigint), :usageScope, now(), now())',
          { resourceId, employeeId: p.employeeId, departmentId: p.departmentId, usageScope: p.usageScope },
        );
      }

      await db.execute('DELETE FROM resource_attribute WHERE resource_id = CAST(:resourceId AS bigint)', { resourceId });
      for (const a of attributes) {
        await db.execute(
          'INSERT INTO resource_attribute (resource_id, attribute_name, attribute_value, created_at, updated_at) VALUES (CAST(:resourceId AS bigint), :name, :value, now(), now())',
          { resourceId, name: a.name, value: a.value },
        );
      }

      await db.execute('DELETE FROM resource_approver WHERE resource_id = CAST(:resourceId AS bigint)', { resourceId });
      if (approverEmployeeId !== null) {
        await db.query(
          'INSERT INTO resource_approver (resource_id, employee_id, created_at, updated_at) VALUES (CAST(:resourceId AS bigint), CAST(:employeeId AS bigint), now(), now()) RETURNING resource_approver_id AS "resourceApproverId"',
          { resourceId, employeeId: approverEmployeeId },
        );
      }

      const savedPermissions = await db.query(
        'SELECT employee_id AS "employeeId", department_id AS "departmentId", usage_scope AS "usageScope" FROM resource_permission WHERE resource_id = CAST(:resourceId AS bigint) ORDER BY resource_permission_id',
        { resourceId },
      );
      const savedAttributes = await db.query(
        'SELECT attribute_name AS "name", attribute_value AS "value" FROM resource_attribute WHERE resource_id = CAST(:resourceId AS bigint) ORDER BY resource_attribute_id',
        { resourceId },
      );
      const resourceRows = await db.query(
        'SELECT resource_id AS "resourceId", approval_required AS "approvalRequired", visibility_scope AS "visibilityScope" FROM resource WHERE resource_id = CAST(:resourceId AS bigint)',
        { resourceId },
      );
      const approverRows = await db.query(
        'SELECT employee_id AS "approverEmployeeId" FROM resource_approver WHERE resource_id = CAST(:resourceId AS bigint) ORDER BY resource_approver_id',
        { resourceId },
      );

      return {
        resourceId: resourceRows[0].resourceId,
        permissions: savedPermissions,
        attributes: savedAttributes,
        approvalRequired: resourceRows[0].approvalRequired,
        approverEmployeeId: approverRows.length > 0 ? approverRows[0].approverEmployeeId : null,
        visibilityScope: resourceRows[0].visibilityScope,
      };
    });
  }
}

