import { useState } from 'react';
import {
  call,
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Select,
  TextInput,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

interface PermissionDraft {
  kind: string;
  targetId: number | string;
  usageScope: string;
}

interface AttributeDraft {
  name: string;
  value: string;
}

export default function FnSfr03304Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [resourceId, setResourceId] = useState<number | string>('');
  const [permissions, setPermissions] = useState<PermissionDraft[]>([]);
  const [attributes, setAttributes] = useState<AttributeDraft[]>([]);
  const [approvalRequired, setApprovalRequired] = useState('미사용');
  const [approverEmployeeId, setApproverEmployeeId] = useState<number | string>('');
  const [visibilityScope, setVisibilityScope] = useState('전체');
  const [detail, setDetail] = useState<Row | null>(null);

  function start() {
    setResourceId('');
    setPermissions([]);
    setAttributes([]);
    setApprovalRequired('미사용');
    setApproverEmployeeId('');
    setVisibilityScope('전체');
    setOpen(true);
  }

  function updatePermission(index: number, patch: Partial<PermissionDraft>) {
    setPermissions(permissions.map((p, i) => (i === index ? { ...p, ...patch } : p)));
  }

  function updateAttribute(index: number, patch: Partial<AttributeDraft>) {
    setAttributes(attributes.map((a, i) => (i === index ? { ...a, ...patch } : a)));
  }

  async function submit() {
    if (resourceId === '') {
      throw new Error('자원을 선택해 주세요.');
    }
    if (approvalRequired === '사용' && approverEmployeeId === '') {
      throw new Error('승인 절차를 사용하려면 승인 담당자를 지정해 주세요.');
    }
    for (const p of permissions) {
      if (p.targetId === '') {
        throw new Error('사용 권한 대상을 선택해 주세요.');
      }
    }
    for (const a of attributes) {
      if (a.name.trim() === '' || a.value.trim() === '') {
        throw new Error('속성명과 속성값을 모두 입력해 주세요.');
      }
    }
    const body: Row = {
      permissions: permissions.map((p) => ({
        employeeId: p.kind === '임직원' ? p.targetId : null,
        departmentId: p.kind === '부서' ? p.targetId : null,
        usageScope: p.usageScope,
      })),
      attributes: attributes.map((a) => ({ name: a.name, value: a.value })),
      approvalRequired,
      approverEmployeeId: approverEmployeeId === '' ? null : approverEmployeeId,
      visibilityScope,
    };
    const saved = await call('PUT', `/resources/${resourceId}/settings`, role, body);
    setResults([saved, ...results.filter((r) => r['resourceId'] !== saved['resourceId'])]);
    setOpen(false);
    notify('자원 설정을 저장했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>설정 처리</h2>
        <Tiles items={[['이번 처리 자원', results.length]]} />
      </section>
      <section className="box span-8">
        <h2>설정한 자원</h2>
        <Band total={results.length}>
          <button type="button" onClick={start}>자원 설정</button>
        </Band>
        <DataTable
          rows={results}
          empty="설정한 자원이 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'resourceId', label: '자원', render: (r) => <RefName table="resource" role={role} value={r['resourceId']} /> },
            { key: 'approvalRequired', label: '승인 절차 사용 여부', render: (r) => <Badge value={r['approvalRequired']} /> },
            { key: 'approverEmployeeId', label: '승인 담당자', render: (r) => <RefName table="employee" role={role} value={r['approverEmployeeId']} /> },
            { key: 'visibilityScope', label: '공개범위' },
          ]}
        />
      </section>
      {detail && (
        <Drawer title="자원 설정 결과" onClose={() => setDetail(null)}>
          <Field label="자원">
            <RefName table="resource" role={role} value={detail['resourceId']} />
          </Field>
          <Field label="승인 절차 사용 여부">
            <Badge value={detail['approvalRequired']} />
          </Field>
          <Field label="승인 담당자">
            <RefName table="employee" role={role} value={detail['approverEmployeeId']} />
          </Field>
          <Field label="공개범위">
            <span>{String(detail['visibilityScope'] ?? '')}</span>
          </Field>
          <DataTable
            rows={(detail['permissions'] as Row[]) ?? []}
            empty="사용 권한 대상이 없습니다."
            columns={[
              { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r['employeeId']} /> },
              { key: 'departmentId', label: '부서', render: (r) => <RefName table="department" role={role} value={r['departmentId']} /> },
              { key: 'usageScope', label: '사용 범위' },
            ]}
          />
          <DataTable
            rows={(detail['attributes'] as Row[]) ?? []}
            empty="자원 속성이 없습니다."
            columns={[
              { key: 'name', label: '속성명' },
              { key: 'value', label: '속성값' },
            ]}
          />
        </Drawer>
      )}
      {open && (
        <Drawer title="자원 사용 권한·승인 절차·공개범위 설정" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="저장">
            <Field label="자원" required>
              <LookupSelect table="resource" role={role} value={resourceId} onChange={setResourceId} />
            </Field>
            <Field label="승인 절차 사용 여부" required>
              <Select
                value={approvalRequired}
                onChange={setApprovalRequired}
                options={[['미사용', '미사용'], ['사용', '사용']]}
              />
            </Field>
            <Field label="승인 담당자" required={approvalRequired === '사용'} hint="승인 절차를 사용하면 반드시 지정합니다.">
              <LookupSelect table="employee" role={role} value={approverEmployeeId} onChange={setApproverEmployeeId} />
            </Field>
            <Field label="공개범위" required>
              <Select
                value={visibilityScope}
                onChange={setVisibilityScope}
                options={[['전체', '전체'], ['부서', '부서'], ['개인', '개인']]}
              />
            </Field>
            <Field label="사용 권한 대상" wide>
              <div>
                {permissions.map((p, i) => (
                  <div key={i}>
                    <Select
                      value={p.kind}
                      onChange={(v) => updatePermission(i, { kind: v, targetId: '' })}
                      options={[['임직원', '임직원'], ['부서', '부서']]}
                    />
                    <LookupSelect
                      table={p.kind === '부서' ? 'department' : 'employee'}
                      role={role}
                      value={p.targetId}
                      onChange={(v) => updatePermission(i, { targetId: v })}
                    />
                    <TextInput
                      value={p.usageScope}
                      onChange={(v) => updatePermission(i, { usageScope: v })}
                      placeholder="사용 범위"
                    />
                    <button type="button" onClick={() => setPermissions(permissions.filter((_, j) => j !== i))}>삭제</button>
                  </div>
                ))}
                <button
                  type="button"
                  onClick={() => setPermissions([...permissions, { kind: '임직원', targetId: '', usageScope: '' }])}
                >
                  대상 추가
                </button>
              </div>
            </Field>
            <Field label="자원 속성" wide>
              <div>
                {attributes.map((a, i) => (
                  <div key={i}>
                    <TextInput value={a.name} onChange={(v) => updateAttribute(i, { name: v })} placeholder="속성명" />
                    <TextInput value={a.value} onChange={(v) => updateAttribute(i, { value: v })} placeholder="속성값" />
                    <button type="button" onClick={() => setAttributes(attributes.filter((_, j) => j !== i))}>삭제</button>
                  </div>
                ))}
                <button type="button" onClick={() => setAttributes([...attributes, { name: '', value: '' }])}>
                  속성 추가
                </button>
              </div>
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
